<template>
  <section class="projectPackagePanel" aria-label="完整项目包">
    <h3>完整项目包</h3><p class="packageIntro">保存制作记录、画布布局、固定版本、引用媒体和成片。可以移交到新目录，也可以作为完整恢复点；生成凭据使用本机配置。</p>
    <div class="packageActions"><el-button type="primary" :loading="starting" :disabled="busy || store.busy || !store.project" @click="createPackage">保存完整项目包</el-button><el-button :loading="reading" :disabled="uploading" @click="loadJobs">刷新记录</el-button></div>
    <p v-if="error" class="packageError" role="alert">{{ error }}</p><p v-for="warning in importWarnings" :key="warning" class="packageHint">{{ warning }}</p>
    <section class="packageImport"><h4>从项目包恢复到新目录</h4><p class="packageHint">上传后查看清单，再填写新项目名称。原项目和已存在目录保持完整。当前支持零幕导出的 ZIP STORE 包，最多 3 GB。</p><label>选择项目包<input ref="fileInput" type="file" accept=".zip" :disabled="busy || starting" @change="selectPackage" /></label><p v-if="uploading" role="status">正在上传 · {{ uploadProgress }}% <el-button size="small" @click="uploadController?.abort()">停止上传</el-button></p>
      <template v-if="inspected"><div class="packageSummary"><strong>{{ inspected.manifest.name }}</strong><span>修订 {{ inspected.manifest.revision }} · {{ inspected.manifest.files.length }} 个文件 · {{ formatBytes(inspected.manifest.totalBytes) }}</span></div><p v-for="warning in inspected.warnings" :key="warning" class="packageHint">{{ warning }}</p><details><summary>查看归集清单与依赖</summary><p class="packageHint">节点：{{ inspected.manifest.dependencies.nodes.join('、') || '无远程节点' }}</p><p v-for="model in inspected.manifest.dependencies.models" :key="`${model.providerId}:${model.modelId}`" class="packageHint">{{ model.providerId }} / {{ model.modelId }}</p><ol class="packageFiles"><li v-for="file in inspected.manifest.files.slice(0, 60)" :key="file.path"><span>{{ file.path }}</span><small>{{ formatBytes(file.size) }} · SHA {{ file.hash.slice(0, 12) }}</small></li></ol><p v-if="inspected.manifest.files.length > 60" class="packageHint">显示前 60 项，完整清单位于包内 packageManifest.json。</p></details>
        <div class="importDestination"><label>恢复到此文件夹<input :value="targetParent" readonly /></label></div><label>新项目文件夹<input v-model="folderName" maxlength="180" :disabled="busy" /></label><el-button type="primary" :disabled="!targetParent || !folderName.trim() || busy" @click="restore">校验并恢复到新目录</el-button>
      </template>
    </section>
    <section v-if="jobs.length" class="packageHistory" aria-label="项目归集记录"><h4>归集与恢复记录</h4><article v-for="job in jobs.toReversed()" :key="job.jobId"><header><strong>{{ job.kind === 'export' ? '完整项目包' : '恢复到新目录' }}</strong><span>{{ new Date(job.createdAt).toLocaleString() }}</span></header><p role="status">{{ job.status === 'running' ? `${job.phase} · ${formatBytes(job.bytes)} / ${formatBytes(job.totalBytes)}` : statusLabels[job.status] }}</p><p v-if="job.error" class="packageError">{{ job.error }}</p><p v-for="warning in job.warnings" :key="warning" class="packageHint">{{ warning }}</p><div class="packageJobActions"><el-button v-if="job.status === 'running'" @click="cancel(job.jobId)">停止操作</el-button><template v-if="job.status === 'completed' && job.kind === 'export' && job.path"><el-button @click="download(job)">下载项目包</el-button><el-button @click="useSavedPackage(job)">用此包恢复</el-button></template><el-button v-if="job.resultDirectory" @click="openRestored(job)">打开恢复的项目</el-button></div><p v-if="job.resultDirectory" class="packageHint">{{ job.resultDirectory }}</p></article></section>
  </section>
</template>

<script setup lang="ts">
import { computed, inject, onScopeDispose, ref, watch } from "vue";
import axios from "axios";
import { ElMessage } from "element-plus";
import useWorkspaceFiles from "@/lib/workspaceFiles";
import { productionError, useProductionStore } from "@/stores/production";
type Manifest = { name: string; revision: number; totalBytes: number; files: { path: string; size: number; hash: string }[]; dependencies: { nodes: string[]; models: { providerId: string; modelId: string }[] } };
type Job = { jobId: string; directory: string; kind: "export" | "import"; status: "running" | "completed" | "failed" | "cancelled"; phase: string; bytes: number; totalBytes: number; createdAt: number; path?: string; resultDirectory?: string; error?: string; warnings: string[] };
const store = useProductionStore(); const headers = { "x-toonflow-workspace": "1" };
const flushProject = inject<() => Promise<void>>("flushProductionProject"); const openProject = inject<(directory: string) => Promise<void>>("openProductionProject");
const jobs = ref<Job[]>([]); const inspected = ref<{ manifest: Manifest; warnings: string[] }>(); const packagePath = ref(""); const packageDirectory = ref("");
const starting = ref(false); const uploading = ref(false); const uploadProgress = ref(0); const reading = ref(false); const error = ref(""); const targetParent = ref(""); const folderName = ref(""); const importWarnings = ref<string[]>([]);
const fileInput = ref<HTMLInputElement>(); let uploadController: AbortController | undefined; let reader: AbortController | undefined; let timer: ReturnType<typeof setTimeout> | undefined; let epoch = 0;
const active = computed(() => store.visible && store.panel === "packages"); const busy = computed(() => starting.value || uploading.value || jobs.value.some(job => job.status === "running"));
const statusLabels = { running: "处理中", completed: "已完成", failed: "未完成，原项目保留", cancelled: "已停止" };
function formatBytes(value: number) { return value >= 1024 ** 3 ? `${(value / 1024 ** 3).toFixed(2)} GB` : value >= 1024 ** 2 ? `${(value / 1024 ** 2).toFixed(2)} MB` : `${Math.round(value / 1024)} KB`; }
async function request<T>(name: string, body: Record<string, unknown>) { const { data } = await axios.post<{ data: T }>(`/api/production/packages/${name}`, body, { headers }); return data.data; }
async function loadJobs() {
  clearTimeout(timer); reader?.abort(); const directory = store.directory; if (!active.value || !directory) return;
  const current = reader = new AbortController(); reading.value = true;
  try { const { data } = await axios.get<{ data: Job[] }>("/api/production/packages/jobs", { params: { directory }, headers, signal: current.signal }); if (!current.signal.aborted && directory === store.directory) jobs.value = data.data.sort((a, b) => a.createdAt - b.createdAt); }
  catch (cause) { if (!current.signal.aborted && directory === store.directory) error.value = productionError(cause); }
  finally { if (!current.signal.aborted && directory === store.directory) { reading.value = false; if (active.value) timer = setTimeout(loadJobs, 1500); } }
}
async function createPackage() {
  const directory = store.directory; starting.value = true; error.value = "";
  try { await flushProject?.(); await store.load(); if (directory !== store.directory || !store.project) throw new Error("项目已切换，请重新打包"); await request("export", { directory, expectedRevision: store.project.revision, jobId: crypto.randomUUID() }); await loadJobs(); }
  catch (cause) { if (directory === store.directory) error.value = productionError(cause); } finally { starting.value = false; }
}
async function inspect(directory: string, path: string) { const result = await request<{ manifest: Manifest; warnings: string[] }>("inspect", { directory, path }); if (directory !== store.directory) return; inspected.value = result; packagePath.value = path; packageDirectory.value = directory; folderName.value = `${result.manifest.name}恢复`.replace(/[\\/:*?"<>|]/g, "").slice(0, 180); }
async function selectPackage(event: Event) {
  const file = (event.target as HTMLInputElement).files?.[0]; if (!file) return; const directory = store.directory; const token = ++epoch; uploadController?.abort(); const controller = uploadController = new AbortController(); uploading.value = true; uploadProgress.value = 0; inspected.value = undefined; error.value = "";
  try { if (file.size > 3 * 1024 ** 3) throw new Error("项目包不能超过 3 GB"); const { data } = await axios.put<{ data: { path: string } }>("/api/production/packages/upload", file, { params: { directory, uploadId: crypto.randomUUID() }, headers: { ...headers, "content-type": "application/octet-stream" }, signal: controller.signal, onUploadProgress: progress => { uploadProgress.value = Math.min(100, Math.round(progress.loaded / file.size * 100)); } }); if (token !== epoch || directory !== store.directory) return; await inspect(directory, data.data.path); }
  catch (cause) { if (token === epoch && directory === store.directory) error.value = controller.signal.aborted ? "上传已停止，原项目保持完整" : productionError(cause); } finally { if (token === epoch) uploading.value = false; if (fileInput.value) fileInput.value.value = ""; }
}
async function restore() { if (starting.value) return; starting.value = true; error.value = ""; const directory = packageDirectory.value; try { if (directory !== store.directory) throw new Error("原项目已切换，请重新选择项目包"); await request("import", { directory, path: packagePath.value, targetParent: targetParent.value, folderName: folderName.value.trim(), jobId: crypto.randomUUID() }); await loadJobs(); } catch (cause) { error.value = productionError(cause); } finally { starting.value = false; } }
async function useSavedPackage(job: Job) { try { await inspect(job.directory, job.path!); } catch (cause) { error.value = productionError(cause); } }
async function cancel(jobId: string) { try { await request("cancel", { directory: store.directory, jobId }); await loadJobs(); } catch (cause) { error.value = productionError(cause); } }
async function download(job: Job) { try { const url = await useWorkspaceFiles(job.directory).previewUrl(job.path!); const link = document.createElement("a"); link.href = url; link.download = `${store.project?.name || 'project'}.zeromu.zip`; link.click(); } catch (cause) { error.value = productionError(cause); } }
async function openRestored(job: Job) { try { if (!job.resultDirectory || !openProject) return; await openProject(job.resultDirectory); ElMessage.success("已打开独立恢复目录"); } catch (cause) { error.value = productionError(cause); } }
watch(() => store.directory, async directory => { ++epoch; uploadController?.abort(); reader?.abort(); uploading.value = false; starting.value = false; reading.value = false; jobs.value = []; inspected.value = undefined; error.value = ""; packagePath.value = ""; packageDirectory.value = ""; targetParent.value = directory ? directory.replace(/[\\/][^\\/]*$/, "") : ""; importWarnings.value = []; if (directory) try { const state = await useWorkspaceFiles(directory).readJson<{ warnings?: unknown }>("projectImportState.json"); if (directory === store.directory && Array.isArray(state.warnings)) importWarnings.value = state.warnings.filter((value): value is string => typeof value === "string"); } catch { /* 原始项目没有导入说明；制作记录读取会另外报告目录错误。 */ } if (active.value) void loadJobs(); }, { immediate: true });
watch(active, value => { if (value) void loadJobs(); else { reader?.abort(); clearTimeout(timer); } });
onScopeDispose(() => { ++epoch; uploadController?.abort(); reader?.abort(); clearTimeout(timer); });
</script>

<style scoped lang="scss">
.projectPackagePanel { h3 { margin: 0 0 12px; font-size: 18px; } h4 { margin: 28px 0 12px; font-size: 14px; } p { line-height: 1.7; } .packageIntro { max-width: 58ch; font-size: 13px; color: var(--el-text-color-secondary); } .packageHint { font-size: 12px; color: var(--el-text-color-secondary); overflow-wrap: anywhere; } .packageError { font-size: 13px; color: var(--el-color-danger); overflow-wrap: anywhere; } .packageActions, .packageJobActions { display: flex; gap: 8px; flex-wrap: wrap; :deep(.el-button + .el-button) { margin-left: 0; } } .packageImport { margin-top: 28px; padding-top: 4px; border-top: 1px solid var(--el-border-color-light); > label { margin: 14px 0; } input[type='file'] { max-width: 100%; } } .packageSummary { display: flex; flex-wrap: wrap; gap: 12px; margin-top: 20px; align-items: baseline; span { font-size: 12px; color: var(--el-text-color-secondary); } } details { margin: 16px 0; font-size: 13px; summary { cursor: pointer; } } .packageFiles { max-height: 260px; overflow: auto; list-style: none; padding: 0; li { display: flex; flex-wrap: wrap; gap: 8px; justify-content: space-between; border-bottom: 1px solid var(--el-border-color-light); padding: 8px 0; span { font-size: 12px; overflow-wrap: anywhere; min-width: 0; } small { color: var(--el-text-color-secondary); font-variant-numeric: tabular-nums; } } } .importDestination { display: flex; gap: 8px; align-items: end; margin: 14px 0; > label { flex: 1; min-width: 0; } } .packageHistory { margin-top: 32px; article { border-top: 1px solid var(--el-border-color-light); padding: 16px 0; header { display: flex; flex-wrap: wrap; gap: 12px; align-items: baseline; strong { font-size: 14px; } span { font-size: 12px; color: var(--el-text-color-secondary); } } > p { font-size: 12px; } } } }
</style>
